uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); (r/"lean/Demo/Defs.lean").write_text("import Lean\n\nnamespace Demo\n\ndef tag (n : Nat) : Bool := n < 7\n\ndef Small (n : Nat) : Prop := n < 5\n\ninstance (n : Nat) : Decidable (Small n) := Nat.decLt n 5\n\nopen Lean PrettyPrinter in\n@[app_unexpander Small] def unexpandSmall : Unexpander\n  | `($_ $n:num) => if tag n.getNat then `($(mkIdent `tiny) $n) else `($(mkIdent `big) $n)\n  | _ => throw ()\n\n/--\nerror: Expression\n  decide (big 7)\ndid not evaluate to `true`\n-/\n#guard_msgs in\n#guard decide (Small 7)\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"tag")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
